function longestEvenSlice(s: string): number {
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    const c = [0, 0, 0];
    for (let j = i; j < s.length; j++) {
      c[s.charCodeAt(j) - 97]++;
      const present = c.filter(x => x > 0);
      if (present.every(x => x === present[0])) best = Math.max(best, j - i + 1);
    }
  }
  return best;
}

