function longestEvenSlice(s: string): number {
  const n = s.length;
  let best = 0;
  // one letter: longest run
  for (let i = 0, run = 0; i < n; i++) {
    run = i > 0 && s[i] === s[i - 1] ? run + 1 : 1;
    best = Math.max(best, run);
  }
  // two letters, the third one absent
  for (const [x, y, z] of [["a", "b", "c"], ["a", "c", "b"], ["b", "c", "a"]]) {
    let diff = 0, first = new Map<number, number>([[0, -1]]);
    for (let i = 0; i < n; i++) {
      if (s[i] === z) { diff = 0; first = new Map([[0, i]]); continue; }
      diff += s[i] === x ? 1 : -1;
      const f = first.get(diff);
      if (f !== undefined) best = Math.max(best, i - f);
      else first.set(diff, i);
    }
  }
  // all three letters
  const first = new Map<number, number>();
  const W = 2 * n + 1;
  let a = 0, b = 0, c = 0;
  first.set(n * W + n, -1); // key for (0, 0)
  for (let i = 0; i < n; i++) {
    if (s[i] === "a") a++; else if (s[i] === "b") b++; else c++;
    const key = (a - b + n) * W + (b - c + n);
    const f = first.get(key);
    if (f !== undefined) best = Math.max(best, i - f);
    else first.set(key, i);
  }
  return best;
}

